EVENT_REGISTRY_RATIFIABLE: Final = True

_REGISTRATIONS_BY_IDENTITY: Final = {
    (registration.full_name, registration.version): registration
    for registration in EVENT_REGISTRATIONS
}


def require_event_registration(
    full_name: str, version: int, content_type: str
) -> EventRegistration:
    """Return the exact registration or reject an unsupported envelope."""
    registration = _REGISTRATIONS_BY_IDENTITY.get((full_name, version))
    if registration is None:
        raise ValueError(f"unregistered event type/version: {full_name}@{version}")
    if registration.content_type != content_type:
        raise ValueError(
            f"event content type mismatch: expected {registration.content_type}, got {content_type}"
        )
    return registration
